/*
 * A183120  Magnetic Tower of Hanoi, number of moves of disk number k,
 *          generated by a certain algorithm, yielding a "forward moving"
 *          non-optimal solution of the [RED ; NEUTRAL ; NEUTRAL] or [NEUTRAL
 *          ; NEUTRAL ; BLUE] pre-colored puzzle.
 * https://oeis.org/A183120
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(0)=0, a(1)=1, a(2)=3, a(3)=7; a(n) = 3*a(n-1) - 2*n + 6 for
 *            even n ≥ 4 a(n) = 3*a(n-1) - 2*n + 8 for odd n ≥ 5 (This
 *            recurrence generates all terms of OEIS A183120.)
 * Range:     u8 n <= 6, u16 n <= 11, u32 n <= 21, u64 n <= 28, u128 n <= 28,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* Handle the initial values explicitly. */
    if (n == 0u) return (seq_t)0;
    if (n == 1u) return (seq_t)1;
    if (n == 2u) return (seq_t)3;
    if (n == 3u) return (seq_t)7;

    /* Start from a(3) and iterate up to n using the parity‑dependent
       recurrence. The loop runs at most n‑3 iterations, which is well
       within the time limits for n up to 10000. */
    seq_t prev = (seq_t)7; /* a(3) */

    for (idx_t i = 4u; i <= n; ++i) {
        seq_t val = prev * (seq_t)3;                /* 3*a(i-1) */
        val -= (seq_t)2 * (seq_t)i;                 /* -2*i   */
        if ((i & 1u) == 0u) {                      /* even i */
            val += (seq_t)6;
        } else {                                   /* odd i */
            val += (seq_t)8;
        }
        prev = val;
    }
    return prev;
}
